//! Single owned disposable Client/service composition; engine facts injected.
use super::*;
#[derive(Clone,Default)]struct FailProofStore{inner:MemoryStore,fail:Arc<std::sync::atomic::AtomicBool>,failed:Arc<AtomicU64>}
impl CredentialStore for FailProofStore{
 fn save(&self,p:&ServiceProfile,b:&SecretBlob)->Result<(),crate::secrets::StoreError>{if b.bytes().windows(9).any(|v|v==b"\"proof\":\"")&&self.fail.swap(false,Ordering::AcqRel){self.failed.fetch_add(1,Ordering::AcqRel);return Err(crate::secrets::StoreError::Unavailable)}self.inner.save(p,b)}
 fn load(&self,p:&ServiceProfile)->Result<Option<SecretBlob>,crate::secrets::StoreError>{self.inner.load(p)}
 fn delete(&self,p:&ServiceProfile)->Result<(),crate::secrets::StoreError>{self.inner.delete(p)}
}
fn fresh(store:FailProofStore,device:uuid::Uuid,root:std::path::PathBuf,http:reqwest::Client)->Core<FailProofStore>{
 let mut c=Core::new(store,device,Arc::new(Mutex::new(None)),root);c.http=http;c.open_browser=false;std::fs::create_dir_all(&c.claims_root).unwrap();c.enable_g3(&c.claims_root.join("journal.jsonl"),Arc::new(Mutex::new(nt2_desktop_g0::g3_runtime::Exchange::default()))).unwrap();c
}
async fn setup(c:&mut Core<FailProofStore>,origin:&str,subject:&str){
 c.select(origin,"",false).await.unwrap();registered_as(c,subject).await;c.request_social(Arc::new(Mutex::new(nt2_desktop_g0::g3_social_stream::Exchange::default()))).unwrap();c.social_profile=Some(nt2_desktop_g0::g3_social_installation::development_profile().unwrap()["profile"].clone());c.configure_game(&std::env::var("NT2_FLOW_GAME_FIXTURE").unwrap()).unwrap();c.enable_automatic_setup();c.create_fixture(false).await.unwrap();
 crate::handoff::coherent_startup(&mut c.pending.lock().unwrap(),nt2_local_ws::owner::Id::OsProcess(std::process::id()),[7;16]).unwrap();facts(c,1,true);*c.expected_game.lock().unwrap()=Some(crate::pipe::verified_process_path(&std::env::current_exe().unwrap()).unwrap());c.game_tick().await.unwrap();
}
async fn enrolled(c:&mut Core<FailProofStore>,health:&mut health::HealthRunner<FailProofStore>)->(nt2_desktop_g0::startup_local::WaitingMarker,Option<String>){
 let until=Instant::now()+Duration::from_secs(20);let mut sequence=1;let mut uncertain=None;
 while c.waiting_startup_marker().is_none(){assert!(Instant::now()<until,"canonical waiting proof not published: {:?}",c.status_error);sequence+=1;facts(c,sequence,true);let _=health.pump().await;c.sync_health();assert!(!c.pending.lock().unwrap().as_ref().unwrap().release);
  if c.store.failed.load(Ordering::Acquire)>0&&uncertain.is_none(){assert!(c.waiting_startup_marker().is_none(),"Partial proof commit published marker");let bundle=c.pending.lock().unwrap().as_ref().unwrap().startup_bundle.clone().unwrap();let marker=bundle.marker(u64::from(bundle.seed())).unwrap();let j=nt2_desktop_g0::waiting_local::load(&super::super::rejoin::ResumeStore(c.store.clone()),bundle.scope(),&marker).unwrap().unwrap();assert!(j.proof.is_none());uncertain=j.operation.as_ref().and_then(|op|op.request.request_id.clone());assert!(uncertain.is_some());}
  tokio::time::sleep(Duration::from_millis(100)).await;
 }
 let marker=c.waiting_startup_marker().unwrap();c.publish_waiting_metadata();assert_eq!(c.native_diagnostics.lock().unwrap().rejoin.metadata.as_ref().unwrap().2,marker.encode().unwrap());assert!(c.resume_intent.association().is_none());(marker,uncertain)
}
