 let until=Instant::now()+Duration::from_secs(15);let mut recovery_error=None;while c.game.is_none(){assert!(Instant::now()<until,"cold waiting recovery failed: {recovery_error:?}");if c.pending.lock().unwrap().is_some(){facts(&mut c,1,true)}if let Err(e)=c.waiting_tick().await{recovery_error=Some(e)}assert!(c.pending.lock().unwrap().as_ref().is_none_or(|p|!p.release));tokio::time::sleep(Duration::from_millis(100)).await;}
 assert!(c.preparation.is_none());assert!(c.resume_intent.association().is_none());let ctx=c.connection_context().unwrap();assert_eq!(ctx.world,j.intent.as_ref().unwrap().world_token.clone().unwrap());assert!(ctx.original_start.is_none()&&ctx.ownership.is_none()&&!ctx.recovered);
 let mut health=c.health_runner();facts(&mut c,1,true);let _=health.pump().await;c.sync_health();assert!(!c.pending.lock().unwrap().as_ref().unwrap().release);c.collect_inspection().await.unwrap();c.final_start(vec![c.desktop.as_ref().unwrap().id.clone()],vec![]).await.unwrap();
 for n in 2..=6{tokio::time::sleep(Duration::from_millis(2050)).await;facts(&mut c,n,n==2);let result=health.pump().await;c.sync_health();if n==2{assert!(c.pending.lock().unwrap().as_ref().unwrap().release,"real Start failed initial admission: {result:?}")}}
